<template>
  <main class="borrow-page"><header><span>MY LIBRARY</span><h1>我的借阅</h1><p>读者编号 {{ readerId || '—' }} · 跨校借阅记录会显示馆藏所属站点</p></header><section class="borrow-panel"><div class="summary"><div><strong>{{ rows.filter(r=>r.borrow_status==='BORROWED').length }}</strong><span>借阅中</span></div><div><strong>{{ rows.filter(r=>r.borrow_type==='CROSS_CAMPUS'||r.borrow_type==='CROSS_UNIVERSITY').length }}</strong><span>跨校借阅</span></div><div><strong>{{ rows.length }}</strong><span>全部记录</span></div></div><div class="record-list"><article v-for="row in rows" :key="Number(row.borrow_id)"><div class="book-mark">{{ String(row.title).slice(0,1) }}</div><div class="record-main"><span>{{ row.borrow_type }} · COPY {{ row.copy_id }}</span><h2>{{ row.title }}</h2><p>借出：{{ fmt(row.borrow_time) }}　应还：{{ fmt(row.due_time) }}</p></div><div class="record-status" :class="String(row.borrow_status).toLowerCase()"><strong>{{ row.borrow_status }}</strong><span>馆藏 Site {{ row.copy_owner_site_id }}</span></div></article><el-empty v-if="!loading&&!rows.length" description="暂无借阅记录"/></div></section><el-alert v-if="error" :title="error" type="error" :closable="false"/></main>
</template>
<script setup lang="ts">
import { onMounted,ref } from 'vue';import { apiErrorMessage,getMyBorrowings } from '@/api/client';import type { DataRow } from '@/types';const rows=ref<DataRow[]>([]),readerId=ref(0),loading=ref(false),error=ref('');function fmt(v:unknown){return v?new Date(String(v)).toLocaleString('zh-CN'):'—'}onMounted(async()=>{loading.value=true;try{const r=await getMyBorrowings();rows.value=r.rows;readerId.value=r.reader_id}catch(e){error.value=apiErrorMessage(e)}finally{loading.value=false}})
</script>
